namespace Pulsewave.Themes;

/// <summary>
/// The Lumen design tokens: Pulsewave's baseline look, shared by the Lumen templates (generated by
/// src/Tests/Themes/LumenTemplates.cs) and the HUD's touch pages (OneUi.cs), so both draw from one set of colors and
/// fonts. New templates, widgets and pages start from these; see docs/DESIGN.md for how they are used.
/// Colors are "#AARRGGBB", as in theme files.
/// </summary>
public static class Lumen
{
    // Text: white for readings and titles, Soft for running text, Dim for captions and labels.
    public const string Text = "#FFFFFFFF", Soft = "#FFC9D1E0", Dim = "#FFA3ADC2";

    // Accents: cyan is the CPU and the main accent, magenta the GPU and the game, violet memory and the end of the
    // accent gradient (cyan to violet), blue the end of the CPU's arc, warm the sun and limit warnings.
    public const string Cyan = "#FF4DE8FF", Blue = "#FF5B8CFF", Violet = "#FFA78BFF", Magenta = "#FFFF5CCB", Warm = "#FFFFC56B";

    /// <summary>Text and icons on an accent fill (a button that is on).</summary>
    public const string OnText = "#FF04121A";

    // Glass over the canvas: the track of a bar or gauge, a hairline edge, a button or tile.
    public const string Track = "#1FFFFFFF", Edge = "#26FFFFFF", Button = "#1CFFFFFF";

    // A glass slab or card: a little lighter at the top; its edge catches the light along the top.
    public const string SlabTop = "#17FFFFFF", SlabBottom = "#08FFFFFF", SlabHighlight = "#8CFFFFFF";

    // A round glass button or pill.
    public const string ButtonTop = "#26FFFFFF", ButtonBottom = "#0DFFFFFF", ButtonEdge = "#40FFFFFF";

    // The canvas: near-black, a shade lighter at the top.
    public const string Canvas = "#FF04050A", CanvasTop = "#FF070912", CanvasBottom = "#FF030408";

    // The aurora's three lights (cyan, violet, magenta), without their opacity.
    public const string AuroraCyan = "12A8E0", AuroraViolet = "6A45F0", AuroraMagenta = "E0409C";

    // Fonts: DIN numerals and labels (Bahnschrift ships with Windows 10 and 11), Segoe UI for running text.
    public const string Ui = "Segoe UI", Din = "Bahnschrift", DinLight = "Bahnschrift Light", DinSemi = "Bahnschrift SemiBold",
        Icons = "Segoe Fluent Icons", Symbols = "Segoe UI Symbol";

    /// <summary>Capitals with a hair space between the letters: the one caption style (theme text and WPF have no letter-spacing).</summary>
    public static string Spaced(string text) => string.Join(' ', text.ToUpperInvariant().ToCharArray());

    /// <summary>Whether a built-in template's file name belongs to the Lumen family ("40-lumen", "43-lumen-gaming-column").</summary>
    public static bool IsLumen(string templateName) => templateName.Contains("-lumen", StringComparison.OrdinalIgnoreCase);
}
